//! Settings kept between runs in %APPDATA%\SigmaDesk\config.json (Parsec keeps its own in
//! %APPDATA%\Parsec\config.json, MECHANICS.md section 1).

use serde::{Deserialize, Serialize};
use sigmadesk::consts::{PEER_ID_LEN, REGISTRY_PORT};
use sigmadesk::random_id;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub server_url: String,
    pub email: String,
    pub session_id: String,
    pub user_name: String,
    /// This computer's id in the node list.
    pub peer_id: String,
    pub device_id: String,
    pub host_enabled: bool,
    pub host_name: String,
    pub host_desc: String,
    pub host_public: bool,
    pub max_guests: u32,
    /// This computer's RustDesk ID, sent with each heartbeat.
    pub rustdesk_id: String,
    pub rustdesk_path: String,
    pub id_server: String,
    pub relay_server: String,
    pub server_key: String,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            server_url: format!("http://127.0.0.1:{REGISTRY_PORT}"),
            email: String::new(),
            session_id: String::new(),
            user_name: String::new(),
            peer_id: random_id(PEER_ID_LEN),
            device_id: random_id(PEER_ID_LEN),
            host_enabled: false,
            host_name: std::env::var("COMPUTERNAME").unwrap_or_else(|_| "내 컴퓨터".into()),
            host_desc: String::new(),
            host_public: false,
            max_guests: 1,
            rustdesk_id: String::new(),
            rustdesk_path: String::new(),
            id_server: String::new(),
            relay_server: String::new(),
            server_key: String::new(),
        }
    }
}

fn path() -> PathBuf {
    let base = std::env::var("APPDATA").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from("."));
    base.join("SigmaDesk").join("config.json")
}

impl Config {
    pub fn load() -> Config {
        std::fs::read_to_string(path())
            .ok()
            .and_then(|t| serde_json::from_str(&t).ok())
            .unwrap_or_default()
    }

    pub fn save(&self) {
        let p = path();
        if let Some(dir) = p.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Ok(text) = serde_json::to_string_pretty(self) {
            let _ = std::fs::write(p, text);
        }
    }
}

//! Talks to the SigmaDesk registry server on a background thread, the way Parsec's client calls
//! kessel-api (MECHANICS.md section 2). The UI sends a Job and reads Replies each frame.

use sigmadesk::consts::{APP_VERSION, MAX_HOSTS, SESSION_SCOPES};
use sigmadesk::proto::*;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::time::Duration;

pub enum Job {
    Login { server: String, email: String, password: String, peer_id: String },
    Signup { server: String, email: String, password: String, name: String },
    Hosts { server: String, session: String, peer_id: String },
    Me { server: String, session: String },
    Heartbeat { server: String, session: String, beat: Heartbeat },
    Remove { server: String, session: String, peer_id: String },
}

pub enum Reply {
    LoggedIn(AuthResponse),
    Hosts(Vec<Host>),
    Me(MeResponse),
    HeartbeatOk,
    Removed(String),
    /// error text, and whether the session is no longer valid (HTTP 401/403 log out, like Parsec)
    Failed(String, bool),
}

pub struct Net {
    tx: Sender<Job>,
    pub rx: Receiver<Reply>,
}

impl Net {
    pub fn start(ctx: eframe::egui::Context) -> Net {
        let (tx, jobs) = channel::<Job>();
        let (out, rx) = channel::<Reply>();
        std::thread::spawn(move || {
            let agent = ureq::AgentBuilder::new()
                .timeout_connect(Duration::from_secs(5))
                .timeout(Duration::from_secs(10))
                .build();
            for job in jobs {
                let reply = run(&agent, job);
                if out.send(reply).is_err() {
                    break;
                }
                ctx.request_repaint();
            }
        });
        Net { tx, rx }
    }

    pub fn send(&self, job: Job) {
        let _ = self.tx.send(job);
    }
}

fn base(server: &str) -> String {
    server.trim().trim_end_matches('/').to_string()
}

fn with_headers(req: ureq::Request, session: &str) -> ureq::Request {
    let req = req
        .set("X-SigmaDesk-OS", std::env::consts::OS)
        .set("X-SigmaDesk-Platform", std::env::consts::OS)
        .set("X-SigmaDesk-App-Version", APP_VERSION);
    if session.is_empty() {
        req
    } else {
        req.set("Authorization", &format!("Bearer {session}"))
    }
}

fn fail(e: ureq::Error) -> Reply {
    match e {
        ureq::Error::Status(code, resp) => {
            let body: Option<ErrorResponse> = resp.into_json().ok();
            let text = body
                .map(|b| if b.message.is_empty() { b.error } else { b.message })
                .unwrap_or_else(|| format!("서버 오류 {code}"));
            Reply::Failed(text, code == 401 || code == 403)
        }
        ureq::Error::Transport(t) => Reply::Failed(format!("서버에 연결할 수 없습니다 ({})", t.kind()), false),
    }
}

fn run(agent: &ureq::Agent, job: Job) -> Reply {
    match job {
        Job::Login { server, email, password, peer_id } => {
            let body = AuthRequest {
                email,
                password,
                session_scopes: SESSION_SCOPES.iter().map(|s| s.to_string()).collect(),
                host_peer_id: Some(peer_id),
            };
            match with_headers(agent.post(&format!("{}/v2/auth", base(&server))), "").send_json(&body) {
                Ok(r) => r.into_json().map(Reply::LoggedIn).unwrap_or_else(|e| Reply::Failed(e.to_string(), false)),
                Err(e) => fail(e),
            }
        }
        Job::Signup { server, email, password, name } => {
            let body = SignupRequest { email, password, name };
            match with_headers(agent.post(&format!("{}/v2/signup", base(&server))), "").send_json(&body) {
                Ok(r) => r.into_json().map(Reply::LoggedIn).unwrap_or_else(|e| Reply::Failed(e.to_string(), false)),
                Err(e) => fail(e),
            }
        }
        Job::Hosts { server, session, peer_id } => {
            let req = with_headers(agent.get(&format!("{}/v2/hosts?mode=desktop", base(&server))), &session)
                .set("X-SigmaDesk-Peer-Id", &peer_id);
            match req.call() {
                Ok(r) => match r.into_json::<HostsResponse>() {
                    Ok(mut h) => {
                        h.data.truncate(MAX_HOSTS);
                        Reply::Hosts(h.data)
                    }
                    Err(e) => Reply::Failed(e.to_string(), false),
                },
                Err(e) => fail(e),
            }
        }
        Job::Me { server, session } => match with_headers(agent.get(&format!("{}/me", base(&server))), &session).call() {
            Ok(r) => r.into_json().map(Reply::Me).unwrap_or_else(|e| Reply::Failed(e.to_string(), false)),
            Err(e) => fail(e),
        },
        Job::Heartbeat { server, session, beat } => {
            match with_headers(agent.post(&format!("{}/v2/hosts/heartbeat", base(&server))), &session).send_json(&beat) {
                Ok(_) => Reply::HeartbeatOk,
                Err(e) => fail(e),
            }
        }
        Job::Remove { server, session, peer_id } => {
            match with_headers(agent.post(&format!("{}/v2/hosts/remove", base(&server))), &session)
                .send_json(&RemoveHost { peer_id: peer_id.clone() })
            {
                Ok(_) => Reply::Removed(peer_id),
                Err(e) => fail(e),
            }
        }
    }
}

//! The RustDesk engine bridge. SigmaDesk does accounts and the node list; the installed RustDesk
//! program does the screen, input and NAT traversal (its hbbs/hbbr servers take the place of
//! Parsec's kessel-ws signalling, STUN and relay, MECHANICS.md sections 3-4).
//!
//! The command-line flags used here (--connect, --password, --get-id, --option) are RustDesk's
//! public behaviour, not something read from Parsec, so they are marked estimated in the sheet.

use std::path::{Path, PathBuf};
use std::process::Command;

#[cfg(windows)]
use std::os::windows::process::CommandExt;
#[cfg(windows)]
const CREATE_NO_WINDOW: u32 = 0x0800_0000;

/// Find rustdesk.exe: the path from settings, then the usual install folders, then PATH.
pub fn find(configured: &str) -> Option<PathBuf> {
    if !configured.trim().is_empty() {
        let p = PathBuf::from(configured.trim());
        if p.is_file() {
            return Some(p);
        }
    }
    let mut candidates: Vec<PathBuf> = Vec::new();
    for var in ["ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA"] {
        if let Ok(dir) = std::env::var(var) {
            candidates.push(Path::new(&dir).join("RustDesk").join("rustdesk.exe"));
        }
    }
    candidates.push(PathBuf::from("/usr/bin/rustdesk"));
    candidates.push(PathBuf::from("/Applications/RustDesk.app/Contents/MacOS/RustDesk"));
    if let Some(p) = candidates.into_iter().find(|p| p.is_file()) {
        return Some(p);
    }
    let paths = std::env::var_os("PATH")?;
    std::env::split_paths(&paths)
        .map(|d| d.join(if cfg!(windows) { "rustdesk.exe" } else { "rustdesk" }))
        .find(|p| p.is_file())
}

fn quiet(cmd: &mut Command) -> &mut Command {
    #[cfg(windows)]
    cmd.creation_flags(CREATE_NO_WINDOW);
    cmd
}

/// Open a remote session to a RustDesk ID.
pub fn connect(exe: &Path, rustdesk_id: &str, password: &str) -> Result<(), String> {
    let id: String = rustdesk_id.chars().filter(|c| !c.is_whitespace()).collect();
    if id.is_empty() {
        return Err("이 컴퓨터에는 RustDesk ID가 등록되어 있지 않습니다".into());
    }
    let mut cmd = Command::new(exe);
    cmd.arg("--connect").arg(&id);
    if !password.is_empty() {
        cmd.arg("--password").arg(password);
    }
    cmd.spawn().map(|_| ()).map_err(|e| format!("RustDesk를 열 수 없습니다: {e}"))
}

/// Ask RustDesk for this computer's ID.
pub fn get_id(exe: &Path) -> Result<String, String> {
    let out = quiet(&mut Command::new(exe)).arg("--get-id").output().map_err(|e| e.to_string())?;
    let text = String::from_utf8_lossy(&out.stdout);
    let id: String = text.lines().map(str::trim).find(|l| !l.is_empty() && l.chars().all(|c| c.is_ascii_alphanumeric())).unwrap_or("").into();
    if id.is_empty() {
        Err("RustDesk가 ID를 알려주지 않았습니다 (RustDesk를 한 번 실행하거나 ID를 직접 입력하세요)".into())
    } else {
        Ok(id)
    }
}

/// Point RustDesk at our own ID/relay servers. RustDesk asks for administrator rights for this.
pub fn apply_servers(exe: &Path, id_server: &str, relay: &str, key: &str) -> Result<(), String> {
    let mut done = 0;
    for (opt, val) in [("custom-rendezvous-server", id_server), ("relay-server", relay), ("key", key)] {
        if val.trim().is_empty() {
            continue;
        }
        let status = quiet(&mut Command::new(exe))
            .args(["--option", opt, val.trim()])
            .status()
            .map_err(|e| e.to_string())?;
        if !status.success() {
            return Err(format!("RustDesk가 '{opt}' 설정을 거절했습니다 (관리자 권한이 필요할 수 있습니다)"));
        }
        done += 1;
    }
    if done == 0 {
        Err("적용할 서버 주소가 없습니다".into())
    } else {
        Ok(())
    }
}

/// Register the sigmadesk:// link so the install web's "connect" buttons open this app
/// (Parsec registers parsec:// the same way, MECHANICS.md section 1). Current user only.
pub fn register_link() -> Result<(), String> {
    let exe = std::env::current_exe().map_err(|e| e.to_string())?;
    let exe = exe.display().to_string();
    let open = format!("\"{exe}\" \"%1\"");
    let steps: [Vec<&str>; 3] = [
        vec!["add", r"HKCU\Software\Classes\sigmadesk", "/ve", "/d", "URL:sigmadesk Protocol", "/f"],
        vec!["add", r"HKCU\Software\Classes\sigmadesk", "/v", "URL Protocol", "/d", "", "/f"],
        vec!["add", r"HKCU\Software\Classes\sigmadesk\shell\open\command", "/ve", "/d", &open, "/f"],
    ];
    for args in steps.iter() {
        let ok = quiet(&mut Command::new("reg")).args(args).status().map(|s| s.success()).unwrap_or(false);
        if !ok {
            return Err("링크 등록에 실패했습니다".into());
        }
    }
    Ok(())
}

/// Pull the peer id out of `sigmadesk://connect/<peer_id>`.
pub fn link_target(arg: &str) -> Option<String> {
    let rest = arg.strip_prefix("sigmadesk://")?;
    let rest = rest.trim_end_matches('/');
    let id = rest.strip_prefix("connect/").unwrap_or(rest);
    if id.is_empty() || !id.chars().all(|c| c.is_ascii_alphanumeric()) {
        None
    } else {
        Some(id.to_string())
    }
}

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
//! SigmaDesk: a Parsec-style remote desktop app. Sign in, see your computers, press Connect.
//! Hosting registers this computer in the online list; the RustDesk engine does the streaming.

mod config;
mod engine;
mod net;
mod ui;

use eframe::egui;
use std::path::PathBuf;

pub struct Args {
    pub screenshot: Option<PathBuf>,
    pub demo: bool,
    pub link: Option<String>,
}

fn parse_args() -> Args {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut args = Args { screenshot: None, demo: false, link: None };
    let mut i = 0;
    while i < argv.len() {
        match argv[i].as_str() {
            "--screenshot" => {
                args.screenshot = argv.get(i + 1).map(PathBuf::from);
                i += 1;
            }
            "--demo" => args.demo = true,
            other => {
                if let Some(peer) = engine::link_target(other) {
                    args.link = Some(peer);
                }
            }
        }
        i += 1;
    }
    args
}

fn main() -> eframe::Result<()> {
    let args = parse_args();
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("SigmaDesk")
            .with_inner_size([1180.0, 740.0])
            .with_min_inner_size([820.0, 560.0]),
        ..Default::default()
    };
    eframe::run_native("SigmaDesk", options, Box::new(move |cc| Ok(Box::new(ui::App::new(cc, args)))))
}

