            }
            if shown.is_empty() {
                let text = if !self.hosts_loaded {
                    "목록을 불러오는 중…"
                } else if q.is_empty() {
                    "아직 등록된 컴퓨터가 없습니다. 원격으로 들어갈 컴퓨터에서 '호스트' 탭을 켜세요."
                } else {
                    "찾는 이름의 컴퓨터가 없습니다."
                };
                ui.label(RichText::new(text).color(DIM));
                return;
            }
            let gap = 16.0;
