//! SigmaDesk server: accounts and user management, the online node list, the install web page,
//! and a relay that carries connections between registered nodes. It plays the part of Parsec's
//! "kessel-api" plus its relay path (offer_relay / answer_relay, MECHANICS.md sections 2-4).
//!
//! sigmadesk-server [--port 21180] [--relay-port 21181] [--relay-host public.name]
//!                  [--data sigmadesk-server.json]
//!                  [--rustdesk-host my.server.com] [--rustdesk-key <public key>]
//!
//! Relay: a viewer asks POST /v2/relay/offer for a node it may use; the server hands out two
//! one-time tickets, one to the viewer and one (through POST /v2/relay/poll) to the node. Both
//! open a TCP connection to the relay port and send "SIGMA-RELAY 1 <ticket>"; when both have
//! arrived the relay answers "OK" to each and copies bytes between them.

use sha2::{Digest, Sha256};
use sigmadesk::consts::*;
use sigmadesk::proto::*;
use sigmadesk::{clean_name, random_id};
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{Shutdown, TcpListener, TcpStream};
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tiny_http::{Header, Method, Request, Response, Server};

#[derive(Clone, serde::Serialize, serde::Deserialize)]
struct User {
    id: u32,
    email: String,
    name: String,
    salt: String,
    pw_hash: String,
    #[serde(default)]
    admin: bool,
    #[serde(default)]
    disabled: bool,
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
struct HostRec {
    owner: u32,
    beat: Heartbeat,
    last_seen_ms: u64,
}

#[derive(Default, serde::Serialize, serde::Deserialize)]
struct Store {
    next_user_id: u32,
    users: Vec<User>,
    hosts: HashMap<String, HostRec>,
    /// session token -> user id
    sessions: HashMap<String, u32>,
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Side {
    Viewer,
    Host,
}

struct Ticket {
    attempt_id: String,
    side: Side,
    expires_ms: u64,
}

/// Relay bookkeeping shared by the web API and the relay listener.
#[derive(Default)]
struct Relay {
    tickets: HashMap<String, Ticket>,
    /// node peer_id -> offers waiting for that node to pick them up
    offers: Hash

