pub fn retry_delay_ms(failures: u32) -> u64 {
    use consts::*;
    use rand::Rng;
    if failures == 0 {
        return 0;
    }
    let mut t = RETRY_START_MS;
    for counter in 0..failures - 1 {
        t = if counter < RETRY_DOUBLING_TRIES { (t * 2).min(RETRY_CAP_MS) } else { RETRY_LONG_WAIT_MS };
    }
