80	fn json_reply<T: serde::Serialize>(code: u16, body: &T) -> Response<std::io::Cursor<Vec<u8>>> {
81	    let text = serde_json::to_string(body).unwrap_or_else(|_| "{}".into());
82	    Response::from_string(text)
83	        .with_status_code(code)
84	        .with_header(Header::from_bytes("Content-Type", "application/json").unwrap())
85	        .with_header(Header::from_bytes("Access-Control-Allow-Origin", "*").unwrap())
86	}
87	
88	fn error(code: u16, err: &str, msg: &str) -> Response<std::io::Cursor<Vec<u8>>> {
89	    json_reply(code, &ErrorResponse { error: err.into(), message: msg.into() })
90	}
91	
92	fn html(body: String) -> Response<std::io::Cursor<Vec<u8>>> {
93	    Response::from_string(body)
94	        .with_header(Header::from_bytes("Content-Type", "text/html; charset=utf-8").unwrap())
95	}
96	
97	fn host_view(rec: &HostRec, users: &[User], viewer_peer: &str, now: u64) -> Host {
98	    let owner = users.iter().find(|u| u.id == rec.owner);
99	    let age = now.saturating_sub(rec.last_seen_ms);
100	    Host {
101	        peer_id: rec.beat.peer_id.clone(),
102	        name: clean_name(&rec.beat.name),
103	        build: rec.beat.app_v.clone(),
104	        players: rec.beat.players,
105	        max_players: rec.beat.max_players,
106	        is_self: rec.beat.peer_id == viewer_peer,
107	        guest_access: rec.beat.public,
108	        event_name: String::new(),
109	        user: HostUser {
110	            id: rec.owner,
111	            name: owner.map(|u| u.name.clone()).unwrap_or_default(),
112	        },
113	        team_id: String::new(),
114	        has_avatar: false,
115	        rustdesk_id: rec.beat.rustdesk_id.clone(),
116	        online: age < OFFLINE_AFTER_MS,
117	        public: rec.beat.public,
118	        desc: rec.beat.desc.clone(),
119	        platform: rec.beat.platform.clone(),
120	        last_seen_secs: age / 1000,
121	    }
122	}
123	
124	fn read_json<T: serde::de::DeserializeOwned>(req: &mut Request) -> Option<T> {
125	    let mut body = String::new();
126	    req.as_reader().take(64 * 1024).read_to_string(&mut body).ok()?;
127	    serde_json::from_str(&body).ok()
128	}
129	
130	fn handle(state: &Arc<Mutex<State>>, mut req: Request) {
131	    let url = req.url().to_string();
132	    let (path, _query) = url.split_once('?').unwrap_or((url.as_str(), ""));
133	    let method = req.method().clone();
134	    let host_hdr = header(&req, "Host").unwrap_or_else(|| format!("localhost:{REGISTRY_PORT}"));
135	    let resp = match (&method, path) {
136	        (Method::Get, "/") => html(install_page(state, &host_hdr)),
137	        (Method::Get, "/nodes") => html(nodes_page(state)),
138	        (Method::Post, "/v2/signup") => match read_json::<SignupRequest>(&mut req) {
139	            Some(s) if s.email.contains('@') && s.password.len() >= 6 => {
140	                let mut st = state.lock().unwrap();
141	                if st.store.users.iter().any(|u| u.email.eq_ignore_ascii_case(&s.email)) {
142	                    error(409, "EMAIL_TAKEN", "이미 등록된 이메일입니다")
143	                } else {
144	                    st.store.next_user_id += 1;
145	                    let salt = random_id(16);
146	                    let user = User {
147	                        id: st.store.next_user_id,
148	                        email: s.email.trim().to_string(),
149	                        name: if s.name.trim().is_empty() { s.email.clone() } else { clean_name(s.name.trim()) },
150	                        pw_hash: hash_pw(&salt, &s.password),
151	                        salt,
152	                    };
153	                    let token = random_id(48);
154	                    st.store.sessions.insert(token.clone(), user.id);
155	                    let reply = AuthResponse { session_id: token, user_id: user.id, user_name: user.name.clone() };
156	                    st.store.users.push(user);
157	                    st.save();
158	                    json_reply(201, &reply)
159	                }
160	            }
161	            _ => error(400, "INVALID_MSG", "이메일과 6자 이상 비밀번호가 필요합니다"),
162	        },
163	        (Method::Post, "/v2/auth") => match read_json::<AuthRequest>(&mut req) {
164	            Some(a) => {
165	                let mut st = state.lock().unwrap();
166	                let user = st.store.users.iter().find(|u| u.email.eq_ignore_ascii_case(a.email.trim())).cloned();
167	                match user {
168	                    Some(u) if hash_pw(&u.salt, &a.password) == u.pw_hash => {
169	                        let token = random_id(48);
170	                        st.store.sessions.insert(token.clone(), u.id);
171	                        st.save();
172	                        json_reply(200, &AuthResponse { session_id: token, user_id: u.id, user_name: u.name })
173	                    }
