21	fn parse_args() -> Args {
22	    let argv: Vec<String> = std::env::args().skip(1).collect();
23	    let mut args = Args { screenshot: None, demo: false, link: None, tab: None };
24	    let mut i = 0;
25	    while i < argv.len() {
26	        match argv[i].as_str() {
27	            "--screenshot" => {
28	                args.screenshot = argv.get(i + 1).map(PathBuf::from);
29	                i += 1;
30	            }
31	            "--demo" => args.demo = true,
32	            "--tab" => {
33	                args.tab = argv.get(i + 1).cloned();
34	                i += 1;
35	            }
36	            other => {
37	                if let Some(peer) = engine::link_target(other) {
38	                    args.link = Some(peer);
39	                }
40	            }
41	        }
42	        i += 1;
43	    }

